AUDITED_INFERENCE="import hashlib,json,runpy,sys\nfrom pathlib import Path\nimport numpy as np,pandas as pd,torch\nimport rsna.infer as inference\nbundle=Path(sys.argv[1]);data=Path(sys.argv[2]);weight=Path(sys.argv[3]);output=Path(sys.argv[4])\nreference=json.loads((bundle/'visible-trained-reference.json').read_text())\nexpected={s['uid']:s for s in reference['studies']};observed={};observed_mirror={}\ntta=reference.get('tta','none')\nif tta not in ('none','anatomical_lr'):raise RuntimeError('Unapproved TTA')\ninput_ids=pd.read_csv(data/'test.csv',dtype={inference.UID:str})[inference.UID].tolist()\nvisible_input=len(input_ids)==len(expected) and set(input_ids)==set(expected)\npartial_inputs=[]\noriginal=inference.build_input\ndef checked_input(uid,rows,root,config):\n    pack,details=original(uid,rows,root,config)\n    if details['decode_failures']:\n        if visible_input:raise RuntimeError('DICOM decode failure: '+uid)\n        partial_inputs.append({'uid':uid,'decode_failures':len(details['decode_failures'])})\n    if visible_input:\n        digest=hashlib.sha256(pack['volume'].tobytes()+pack['mask'].tobytes()).hexdigest()\n        if digest!=expected[uid]['volume_mask_sha256']:raise RuntimeError('Visible input bytes differ: '+uid)\n        observed[uid]=digest\n        if tta=='anatomical_lr':\n            codes=np.asarray(pack['mirror_codes'],dtype=int).tolist()\n            if codes!=expected[uid]['mirror_codes']:raise RuntimeError('Visible anatomical mirror direction differs: '+uid)\n            observed_mirror[uid]=codes\n    print(json.dumps({'input_study':uid,'decode_failures':len(details['decode_failures'])}),flush=True)\n    return pack,details\ninference.build_input=checked_input\nsys.argv=['rsna.infer','--checkpoint',str(weight),'--data',str(data),'--output',str(output)]\nif tta=='anatomical_lr':sys.argv+=['--tta',tta]\ninference.main()\nframe=pd.read_csv(output,dtype={inference.UID:str})\nvisible=len(frame)==len(expected) and set(frame[inference.UID])==set(expected)\nreport={'status':'complete','scope':'full visible parity' if visible else 'non-visible input; visible reference not applicable',\n        'checkpoint_sha256':reference['checkpoint_sha256'],'observed_input_hashes':observed,\n        'partial_inputs':partial_inputs,'partial_input_policy':'frozen preprocessing masks undecodable slices; usable triplets required',\n        'max_probability_tolerance':0.005,'models':1,'fold':0,\n        'runtime':{'torch':torch.__version__,'numpy':np.__version__,'cuda_available':torch.cuda.is_available(),\n                   'device_name':torch.cuda.get_device_name(0) if torch.cuda.is_available() else 'CPU',\n                   'peak_cuda_allocated_bytes':torch.cuda.max_memory_allocated() if torch.cuda.is_available() else 0}}\nif tta=='anatomical_lr':report.update(tta_recipe=reference['tta_recipe'],observed_mirror_codes=observed_mirror)\nif visible:\n    if set(observed)!=set(expected):raise RuntimeError('Missing visible input audit')\n    actual=frame[inference.LABELS].to_numpy(float)\n    wanted=np.array([expected[u]['precision']['float16']['probabilities'] for u in frame[inference.UID]])\n    maximum=float(np.abs(actual-wanted).max());report['max_probability_difference']=maximum\n    if maximum>0.005:raise RuntimeError('Server/Kaggle visible probabilities differ: '+str(maximum))\noutput.with_name('visible-parity.json').write_text(json.dumps(report,indent=2))\n"
import base64,hashlib,io,json,os,subprocess,sys,tarfile,time
from pathlib import Path
started=time.monotonic()
os.environ['HF_HUB_OFFLINE']='1'
os.environ['TRANSFORMERS_OFFLINE']='1'
root=Path('/kaggle/working/rsna_single');root.mkdir(exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(ENCODED)),mode='r:gz') as tar:
    tar.extractall(root,filter='data')
weight_roots=[Path('/kaggle/input')/SLUG,Path('/kaggle/input/datasets')/OWNER/SLUG]
manifests=[p for base in weight_roots if base.is_dir() for p in base.rglob('model.pt')
           if hashlib.sha256(p.read_bytes()).hexdigest()==CHECKPOINT_SHA256]
if len(manifests)!=1:raise RuntimeError('Expected one matching private model bundle')
bundle=manifests[0].parent
uploaded=bundle
bundle=root/'runtime-assets';bundle.mkdir(exist_ok=True)
for name,content in RUNTIME_ASSETS.items():
    (bundle/name).write_text(content)
for name in ['model.pt']+list(json.loads(RUNTIME_ASSETS['wheel-manifest.json'])['wheels']):
    (bundle/name).symlink_to(uploaded/name)
source_manifest=json.loads((bundle/'source-manifest.json').read_text())
assert hashlib.sha256((bundle/'source-manifest.json').read_bytes()).hexdigest()==json.loads(RUNTIME_ASSETS['manifest.json'])['source_snapshot_manifest_sha256']
source_hashes={'rsna/'+p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((root/'rsna').glob('*.py'))}
assert source_hashes==source_manifest['source_hashes'], 'Frozen inference source mismatch'
assert hashlib.sha256(json.dumps(source_hashes,sort_keys=True).encode()).hexdigest()==source_manifest['code_hash']
weight=bundle/'model.pt'
assert hashlib.sha256(weight.read_bytes()).hexdigest()==CHECKPOINT_SHA256
assert hashlib.sha256((bundle/'visible-trained-reference.json').read_bytes()).hexdigest()==VISIBLE_REFERENCE_SHA256
wheel_manifest=json.loads((bundle/'wheel-manifest.json').read_text())
assert wheel_manifest['python_version']==str(sys.version_info.major)+str(sys.version_info.minor), 'Offline wheel Python ABI mismatch'
for filename,metadata in wheel_manifest['wheels'].items():
    assert hashlib.sha256((bundle/filename).read_bytes()).hexdigest()==metadata['sha256'], 'Offline dependency hash mismatch'
assert hashlib.sha256((bundle/'offline-requirements.txt').read_bytes()).hexdigest()==wheel_manifest['requirements_sha256']
subprocess.run([sys.executable,'-m','pip','install','--no-index','--no-deps','--find-links',str(bundle),'-r',str(bundle/'offline-requirements.txt')],check=True)
data=next(p for p in [Path('/kaggle/input/competitions/rsna-knee-abnormality-detection'),
                     Path('/kaggle/input/rsna-knee-abnormality-detection')] if (p/'test.csv').is_file())
env=dict(os.environ,PYTHONPATH=str(root))
subprocess.run([sys.executable,'-P','-c',AUDITED_INFERENCE,str(bundle),str(data),str(weight),'/kaggle/working/submission.csv'],env=env,check=True)
stress=json.loads((bundle/'stress-request.json').read_text())
import pandas as pd
actual_ids=pd.read_csv(data/'test.csv',dtype={'StudyInstanceUID':str})['StudyInstanceUID'].tolist()
reference_ids=[s['uid'] for s in json.loads((bundle/'visible-trained-reference.json').read_text())['studies']]
if stress['study_ids'] and len(actual_ids)==len(reference_ids) and set(actual_ids)==set(reference_ids):
    train_root=next((data/name for name in ['train_images','train_series'] if (data/name).is_dir()),None)
    if train_root is None or not (data/'train_series.csv').is_file():
        raise RuntimeError('Requested visible scale check lacks native training images')
    stress_root=Path('/kaggle/working/stress-input');stress_root.mkdir(exist_ok=True)
    (stress_root/'test_images').symlink_to(train_root,target_is_directory=True)
    pd.DataFrame({'StudyInstanceUID':stress['study_ids']}).to_csv(stress_root/'test.csv',index=False)
    series=pd.read_csv(data/'train_series.csv',dtype={'StudyInstanceUID':str,'SeriesInstanceUID':str})
    series[series['StudyInstanceUID'].isin(stress['study_ids'])].to_csv(stress_root/'test_series.csv',index=False)
    stress_output=Path('/kaggle/working/stress-results');stress_output.mkdir(exist_ok=True)
    subprocess.run([sys.executable,'-P','-c',AUDITED_INFERENCE,str(bundle),str(stress_root),str(weight),str(stress_output/'submission.csv')],env=env,check=True)
    checked=pd.read_csv(stress_output/'submission.csv',dtype={'StudyInstanceUID':str})
    if checked['StudyInstanceUID'].tolist()!=stress['study_ids']:raise RuntimeError('Stress output ID mismatch')
    Path('/kaggle/working/stress-complete.json').write_text(json.dumps({'status':'complete','rows':len(checked),'labels_read':False,'checkpoint_sha256':CHECKPOINT_SHA256,'scope':'native image/resource check only; not hidden-run proof'},indent=2))
Path('/kaggle/working/package-run.json').write_text(json.dumps({'status':'complete','seconds_including_setup':time.monotonic()-started,'checkpoint_sha256':CHECKPOINT_SHA256,'models':1,'fold':0},indent=2))
